from _operator import *
if __name__ == "__main__":
    import sys, os
    if not sys.flags.isolated:
        os.execv(sys.executable, [sys.executable, "-I", __file__, *sys.argv[1:]])
    import json, base64, hashlib
    from pathlib import Path
    path = Path("/tmp/jep-tranche8-worker-20261026.py")
    old_hash = "0e119cb60f001694be7a6816bf5064838d8b1aebf93547d82b48401d2e0df400"
    new_hash = 'b679553cd18e1a71193e4e05c034b117b30ca668e117a8ccecc185e5ec2fde98'
    source = base64.b64decode('', validate=True)
    assert hashlib.sha256(source).hexdigest() == new_hash
    compile(source, str(path), "exec")
    current = path.read_bytes()
    assert hashlib.sha256(current).hexdigest() in {old_hash, new_hash}
    backup = path.with_name("jep-tranche8-worker-20261026-original.py")
    if hashlib.sha256(current).hexdigest() == old_hash:
        if backup.exists():
            assert hashlib.sha256(backup.read_bytes()).hexdigest() == old_hash
        else:
            backup.write_bytes(current)
        temporary = path.with_suffix(".new")
        with temporary.open("wb") as stream:
            stream.write(source); stream.flush(); os.fsync(stream.fileno())
        os.replace(temporary, path)
    print("OPERATOR_RESULT " + json.dumps({"phase":"worker_repair","status":"complete","verification":{"old_worker_sha256":old_hash,"new_worker_sha256":new_hash,"isolated_operator_start":True,"existing_loop_preserved":True,"future_supervisors_repaired":True}}), flush=True)
